import React, { useCallback, useEffect, useState } from "react";
import { StyleSheet, View } from "react-native";
import BottomTabBar from "./BottomTabBar";
import Images from "./images";
import { EventRegister } from "./EventRegister";

const mytabs = [
  {
    name: "Home",
    icon: Images.ic_bottom_tab_home,
  },
  {
    name: "Search",
    icon: Images.ic_bottom_tab_search,
  },
  {
    name: "More",
    icon: Images.ic_bottom_tab_more,
  },
  {
    name: "Message",
    icon: Images.ic_bottom_tab_message,
  },
  {
    name: "Me",
    icon: Images.ic_bottom_tab_me,
  },
];

const TabBar = ({
  navigation,
  tabs = mytabs,
  tabBackgroundColor,
  iconTintColor,
  activeIconTintColor,
  activeBackgroundColor,
  state,
  descriptors,
}) => {
  const [selectTabIndex, setSelectTabIndex] = useState(1);

  useEffect(() => {
    const tabBarIndex = EventRegister.addEventListener(
      "setBottomBarIndex",
      (data) => {
        setSelectTabIndex(data + 1);
      }
    );

    return () => {
      EventRegister.removeEventListener(tabBarIndex);
    };
  }, []);

  useEffect(() => {
    const isFocused = state.index + 1 !== selectTabIndex;
    setSelectTabIndex(state.index + 1);
  }, [state.index]);

  const handlePress = useCallback((tabIndex) => {
    setSelectTabIndex(tabIndex);
    navigation.navigate(tabs[tabIndex - 1].name);
    console.log(tabs);
    console.log(tabIndex);
  }, []);

  return (
    <View style={styles.container}>
      <BottomTabBar
        tabBackgroundColor={tabBackgroundColor}
        iconTintColor={iconTintColor}
        activeIconTintColor={activeIconTintColor}
        activeBackgroundColor={activeBackgroundColor}
        tabs={tabs}
        selectedTabIndex={selectTabIndex}
        selectedIndexCallback={handlePress}
      />
    </View>
  );
};

export default TabBar;

export { EventRegister };

const styles = StyleSheet.create({
  container: {
    height: 68,
    justifyContent: "flex-end",
    paddingTop: 34,
    alignItems: "center",
  },
});
